import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, distance, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, Color, PointLight } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? config?.visual?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'thumbnail-card-home';

  // ---- dimensions ----
  const cardW = 1.8;
  const cardH = 1.18;
  const cardDepth = 0.08;
  const frameDepth = 0.05;
  const captionH = 0.26;

  // ---- accent edge frame (extruded, behind panel) ----
  const frameGeo = new BoxGeometry(cardW + 0.06, cardH + 0.06, frameDepth);
  const frameMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.55,
    metalness: 0.5,
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.12,
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.set(0, 0, -0.035);
  group.add(frame);

  // ---- machined panel body ----
  const panelGeo = new BoxGeometry(cardW, cardH, cardDepth);
  const panelMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.62,
    metalness: 0.42,
    clearcoat: 0.15,
  });
  const panel = new Mesh(panelGeo, panelMat);
  group.add(panel);

  // ---- caption strip (bottom, slightly forward for depth separation) ----
  const captionGeo = new BoxGeometry(cardW - 0.08, captionH, 0.025);
  const captionMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.7,
    metalness: 0.2,
  });
  const caption = new Mesh(captionGeo, captionMat);
  caption.position.set(0, -cardH / 2 + captionH / 2 + 0.05, cardDepth / 2 + 0.02);
  group.add(caption);

  // thin accent underline on caption strip (product-shot accent, <=10% of frame)
  const underlineGeo = new BoxGeometry(cardW - 0.4, 0.02, 0.02);
  const underlineMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.5,
    metalness: 0.4,
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.4,
  });
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(0, caption.position.y - captionH / 2 + 0.03, cardDepth / 2 + 0.035);
  group.add(underline);

  // ---- radial contact shadow beneath the card ----
  const shadowSize = cardW * 1.35;
  const shadowGeo = new PlaneGeometry(shadowSize, shadowSize * 0.72);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const d = distance(uv(), vec2(0.5, 0.5));
  shadowMat.colorNode = new THREE.Color(0x000000);
  shadowMat.opacityNode = smoothstep(0.5, 0.0, d).mul(0.5);
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -cardH / 2 - 0.32, -0.05);
  group.add(shadowPlane);

  // ---- node-local rim light so the machined metal has something to catch ----
  const rimLight = new PointLight(new Color(colors.accent), 1.1, 4.5);
  rimLight.position.set(0.9, 0.6, 1.3);
  group.add(rimLight);

  // ---- centerpiece mesh (gear-a.glb) loaded async, framed within the card ----
  let gearObj = null;
  let disposed = false;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed) return;
      const scene = gltf.scene || (gltf.scenes && gltf.scenes[0]);
      if (!scene) return;
      gearObj = scene;
      gearObj.scale.setScalar(0.85);
      gearObj.position.set(0, 0.16, cardDepth / 2 + 0.05);
      group.add(gearObj);
      gsap.fromTo(
        gearObj.scale,
        { x: 0.01, y: 0.01, z: 0.01 },
        { x: 0.85, y: 0.85, z: 0.85, duration: 0.7, ease: 'power3.out' }
      );
    }).catch(() => {});
  }

  // ---- interaction timelines ----
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(group.position, { y: '+=0.15', duration: 0.5, ease: 'power3.out' }, 0);
  hoverTl.to(group.rotation, { x: -0.05, duration: 0.5, ease: 'power3.out' }, 0);
  hoverTl.to(frameMat, { emissiveIntensity: 0.85, duration: 0.4, ease: 'power2.out' }, 0);
  hoverTl.to(underlineMat, { emissiveIntensity: 1.1, duration: 0.4, ease: 'power2.out' }, 0);

  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
  pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power2.out' });

  function onPointerOver() {
    hoverTl.play();
  }
  function onPointerOut() {
    hoverTl.reverse();
  }
  function onClick() {
    pressTl.restart();
    ctx.emit('hub-home.select', { nodeId: config.id ?? 'thumbnail-card-home' });
  }

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onPointerEnter: onPointerOver,
    onPointerLeave: onPointerOut,
    onClick,
    onPointerDown: onClick,
  };

  group.userData.cleanup = function cleanup() {
    disposed = true;
    hoverTl.kill();
    pressTl.kill();

    frameGeo.dispose();
    frameMat.dispose();
    panelGeo.dispose();
    panelMat.dispose();
    captionGeo.dispose();
    captionMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    if (gearObj) {
      gearObj.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => {
            if (m.map) m.map.dispose();
            m.dispose();
          });
        }
      });
    }

    group.clear();
  };

  return group;
}
